mapper.select:
SELECT g.id, g.name, g.number, g.spec, g.brand, g.unit, g.code, g.data, g.batch, g.protect, g.threshold, c.id as "categoryData.id", c.name as "categoryData.name", COALESCE(SUM(r.nums), 0) as totalStock FROM goods g LEFT JOIN category c ON g.category = c.id LEFT JOIN room r ON r.goods = g.id
AND g.id = #{query.goodsId}
AND g.number LIKE CONCAT('%', #{query.goodsNumber}, '%')
AND EXISTS ( SELECT 1 FROM batch b WHERE b.goods = g.id AND b.number LIKE CONCAT('%', #{query.batchNumber}, '%') )
AND EXISTS ( SELECT 1 FROM batch b WHERE b.goods = g.id AND DATE(b.time) = #{query.productDate} )
AND EXISTS ( SELECT 1 FROM batch b WHERE b.goods = g.id AND b.nums < g.threshold )
AND EXISTS ( SELECT 1 FROM room r3 WHERE r3.goods = g.id AND r3.warehouse IN
#{warehouseId}
)
GROUP BY g.id, c.id ORDER BY g.name

SELECT b.id as batchId, b.room, b.warehouse, w.name as warehouseName, b.goods as goodsId, b.number as batchNumber, b.time as productDate, b.nums FROM batch b LEFT JOIN warehouse w ON b.warehouse = w.id WHERE b.goods IN
#{goodsId}
AND b.number LIKE CONCAT('%', #{query.batchNumber}, '%')
AND DATE(b.time) = #{query.productDate}
AND b.nums < ( SELECT g.threshold FROM goods g WHERE g.id = b.goods )
AND b.warehouse IN
#{warehouseId}
ORDER BY b.number, b.warehouse, b.time
